static void check_test_memory_usage(void)
{
  unsigned int check = ++g_memory_check;
  int ret;

  /* Wait a little bit to let any threads terminate */

  printf("ostest: memory checkpoint %u settle begin\n", check);
  FFLUSH();
  ret = usleep(HALF_SECOND_USEC);
  printf("ostest: memory checkpoint %u settle end ret=%d errno=%d\n",
         check, ret, errno);
  FFLUSH();

  /* Get the current memory usage */

  printf("ostest: memory checkpoint %u mallinfo begin\n", check);
  FFLUSH();
  g_mmafter = mallinfo();
  printf("ostest: memory checkpoint %u mallinfo end\n", check);
  FFLUSH();

  /* Show the change from the previous time */

  printf("\nEnd of test memory usage:\n");
  show_memory_usage(&g_mmprevious, &g_mmafter);

  /* Set up for the next test */

  g_mmprevious = g_mmafter;

  /* If so enabled, show the use of priority inheritance resources */

  dump_nfreeholders("user_main:");
}
